import{_ as t,c as i,o as h,ae as a}from"./chunks/framework.BGWP4WZ_.js";const p=JSON.parse('{"title":"Hướng dẫn tích hợp MCP bên ngoài cho XiaoZhi","description":"","frontmatter":{},"headers":[],"relativePath":"vi/mcp/xiaozhi-mcp.md","filePath":"vi/mcp/xiaozhi-mcp.md"}'),c={name:"vi/mcp/xiaozhi-mcp.md"};function o(r,n,g,l,e,s){return h(),i("div",null,n[0]||(n[0]=[a(`<h1 id="huong-dan-tich-hop-mcp-ben-ngoai-cho-xiaozhi" tabindex="-1">Hướng dẫn tích hợp MCP bên ngoài cho XiaoZhi <a class="header-anchor" href="#huong-dan-tich-hop-mcp-ben-ngoai-cho-xiaozhi" aria-label="Permalink to &quot;Hướng dẫn tích hợp MCP bên ngoài cho XiaoZhi&quot;">​</a></h1><p>Tài liệu này hướng dẫn cách kết nối các dịch vụ MCP bên ngoài vào hệ thống XiaoZhi nhằm mở rộng tính năng và tích hợp công cụ từ bên thứ ba.</p><h2 id="tong-quan" tabindex="-1">Tổng quan <a class="header-anchor" href="#tong-quan" aria-label="Permalink to &quot;Tổng quan&quot;">​</a></h2><p>Bên cạnh các công cụ MCP tích hợp sẵn, hệ thống XiaoZhi còn hỗ trợ kết nối tới các máy chủ MCP bên ngoài để thực hiện:</p><ul><li>Tích hợp công cụ bên thứ ba</li><li>Gọi dịch vụ từ xa</li><li>Triển khai công cụ phân tán</li><li>Chia sẻ công cụ trong cộng đồng</li></ul><h2 id="mo-ta-kien-truc" tabindex="-1">Mô tả kiến trúc <a class="header-anchor" href="#mo-ta-kien-truc" aria-label="Permalink to &quot;Mô tả kiến trúc&quot;">​</a></h2><h3 id="kien-truc-mcp-ket-noi-ngoai" tabindex="-1">Kiến trúc MCP kết nối ngoài <a class="header-anchor" href="#kien-truc-mcp-ket-noi-ngoai" aria-label="Permalink to &quot;Kiến trúc MCP kết nối ngoài&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Nền tảng XiaoZhi AI   xiaozhi-mcphub        Máy chủ MCP ngoài     Công cụ bên thứ ba</span></span>
<span class="line"><span>┌─────────────────┐   ┌─────────────────┐   ┌─────────────────┐   ┌────────────────┐</span></span>
<span class="line"><span>│                 │   │                 │   │                 │   │                │</span></span>
<span class="line"><span>│   MCP Client    │◄──┤ MCP Server/Proxy│◄──┤   MCP Server    │◄──┤ Công cụ thực tế│</span></span>
<span class="line"><span>│                 │   │                 │   │                 │   │                │</span></span>
<span class="line"><span>└─────────────────┘   └─────────────────┘   └─────────────────┘   └────────────────┘</span></span></code></pre></div><h3 id="cac-phuong-thuc-ket-noi" tabindex="-1">Các phương thức kết nối <a class="header-anchor" href="#cac-phuong-thuc-ket-noi" aria-label="Permalink to &quot;Các phương thức kết nối&quot;">​</a></h3><ol><li><strong>Nhập/xuất chuẩn (stdio)</strong>: Khởi chạy tiến trình con và giao tiếp liên tiến trình qua đường ống stdin/stdout, phù hợp với các công cụ CLI cục bộ như Playwright, Amap (Gaode Maps), v.v.</li><li><strong>Sự kiện đẩy từ máy chủ (SSE)</strong>: Giao tiếp luồng sự kiện dựa trên kết nối HTTP dài hạn, cung cấp khả năng trao đổi hai chiều thời gian thực tương tự WebSocket</li><li><strong>HTTP truyền phát (streamable-http)</strong>: Đóng gói giao thức HTTP trên nền TCP, hỗ trợ truyền dữ liệu dạng luồng (streaming), phù hợp cho các dịch vụ API từ xa và microservice</li><li><strong>OpenAPI</strong>: Phương thức kết nối theo đặc tả REST API tiêu chuẩn, tự động phân tích đặc tả OpenAPI và sinh giao diện công cụ, phù hợp với các dịch vụ API bên thứ ba chuẩn hóa</li></ol><h2 id="cac-du-an-ma-nguon-mo-lien-quan" tabindex="-1">Các dự án mã nguồn mở liên quan <a class="header-anchor" href="#cac-du-an-ma-nguon-mo-lien-quan" aria-label="Permalink to &quot;Các dự án mã nguồn mở liên quan&quot;">​</a></h2><p>Các dự án máy khách XiaoZhi do cộng đồng phát triển, cung cấp nhiều cách tích hợp trên các nền tảng khác nhau:</p><h3 id="xiaozhi-mcphub-đi-kem-du-an-nay" tabindex="-1">xiaozhi-mcphub (Đi kèm dự án này) <a class="header-anchor" href="#xiaozhi-mcphub-đi-kem-du-an-nay" aria-label="Permalink to &quot;xiaozhi-mcphub (Đi kèm dự án này)&quot;">​</a></h3><p><strong>XiaoZhi MCP Hub</strong> là hệ thống cầu nối công cụ MCP thông minh được tối ưu riêng cho nền tảng XiaoZhi AI, phát triển dựa trên dự án MCPHub xuất sắc và bổ sung khả năng tích hợp nền tảng XiaoZhi cùng đồng bộ công cụ thông minh.</p><ul><li><strong>Trang dự án</strong>: <a href="https://huangjunsen0406.github.io/xiaozhi-mcphub/" target="_blank" rel="noreferrer">xiaozhi-mcphub</a></li><li><strong>GitHub</strong>: <a href="https://github.com/huangjunsen0406/xiaozhi-mcphub" target="_blank" rel="noreferrer">xiaozhi-mcphub</a></li><li><strong>Tính năng cốt lõi</strong>: <ul><li><strong>Tích hợp nền tảng XiaoZhi AI</strong>: Tự động đồng bộ công cụ qua WebSocket, cập nhật trạng thái thời gian thực, cầu nối giao thức</li><li><strong>Quản lý MCP nâng cao</strong>: Hỗ trợ giao thức stdio, SSE, HTTP, cấu hình cắm nóng (hot-plug), bảng điều khiển tập trung</li><li><strong>Định tuyến công cụ thông minh</strong>: Tìm kiếm công cụ thông minh dựa trên vector và quản lý theo nhóm</li><li><strong>Cơ chế xác thực bảo mật</strong>: Quản lý người dùng bằng JWT + bcrypt, kiểm soát quyền theo vai trò (RBAC)</li><li><strong>Kho MCP tích hợp sẵn</strong>: Cài đặt trực tuyến nhiều công cụ MCP mà không cần khởi động lại, hỗ trợ cập nhật nóng</li></ul></li></ul><h3 id="xiaozhi-client" tabindex="-1">xiaozhi-client <a class="header-anchor" href="#xiaozhi-client" aria-label="Permalink to &quot;xiaozhi-client&quot;">​</a></h3><ul><li><strong>Địa chỉ dự án</strong>: <a href="https://github.com/shenjingnan/xiaozhi-client" target="_blank" rel="noreferrer">xiaozhi-client</a></li><li><strong>Chức năng</strong>: Máy khách XiaoZhi AI chuyên dùng để kết nối và tổng hợp MCP</li><li><strong>Đặc điểm nổi bật</strong>: <ul><li><strong>Hỗ trợ nhiều điểm truy cập</strong>: Cấu hình nhiều điểm truy cập XiaoZhi, cho phép nhiều thiết bị dùng chung một cấu hình MCP</li><li><strong>Tổng hợp MCP Server</strong>: Tổng hợp nhiều MCP Server theo chuẩn chung để quản lý tập trung</li><li><strong>Kiểm soát công cụ động</strong>: Kiểm soát mức độ hiển thị công cụ của MCP Server, tránh lỗi khi số lượng công cụ quá nhiều</li><li><strong>Nhiều cách tích hợp</strong>: Hỗ trợ tích hợp như một MCP Server thông thường vào các máy khách như Cursor/Cherry Studio</li><li><strong>Cấu hình trực quan trên Web</strong>: Giao diện Web UI hiện đại, hỗ trợ cấu hình và quản lý từ xa</li><li><strong>Tích hợp ModelScope</strong>: Hỗ trợ các dịch vụ MCP từ xa được lưu trữ trên ModelScope</li></ul></li></ul><h3 id="hyperchat" tabindex="-1">HyperChat <a class="header-anchor" href="#hyperchat" aria-label="Permalink to &quot;HyperChat&quot;">​</a></h3><ul><li><strong>Địa chỉ dự án</strong>: <a href="https://github.com/BigSweetPotatoStudio/HyperChat" target="_blank" rel="noreferrer">HyperChat</a></li><li><strong>Chức năng</strong>: Không gian làm việc AI thế hệ mới, nền tảng cộng tác thông minh đa nền tảng tiên phong ý tưởng &quot;AI as Code&quot;</li><li><strong>Đặc điểm nổi bật</strong>: <ul><li><strong>AI as Code</strong>: Quản lý năng lực AI theo cấu hình, hỗ trợ quản lý phiên bản và cộng tác nhóm</li><li><strong>Lấy không gian làm việc làm trung tâm</strong>: Cách ly và quản lý môi trường AI theo từng dự án</li><li><strong>Tích hợp sâu hệ sinh thái MCP</strong>: Hỗ trợ đầy đủ giao thức MCP, bộ công cụ tích hợp phong phú và tải động</li><li><strong>Thống nhất đa nền tảng</strong>: Ứng dụng Web, ứng dụng desktop Electron, dòng lệnh CLI, tiện ích mở rộng VSCode</li></ul></li><li><strong>Điểm nhấn kỹ thuật</strong>: <ul><li>Hệ thống tác tử AI cấu hình hóa, hỗ trợ tùy biến Agent chuyên sâu</li><li>So sánh song song nhiều mô hình (Claude, OpenAI, Gemini, v.v.)</li><li>Hiển thị nội dung thông minh (Artifacts, Mermaid, công thức toán học)</li><li>Tác vụ định kỳ và tự động hóa quy trình làm việc (workflow)</li></ul></li></ul>`,19)]))}const d=t(c,[["render",o]]);export{p as __pageData,d as default};
